def _load_embedded(name: str, payload: str):
    mod = types.ModuleType(name)
    mod.__file__ = f'<embedded-{name}>'
    sys.modules[name] = mod
    raw = zlib.decompress(base64.b64decode(payload.encode()))
    exec(compile(raw, mod.__file__, 'exec'), mod.__dict__)
    return mod


