def sha_bytes(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()


def sha_json(obj) -> str:
    return sha_bytes(json.dumps(obj, sort_keys=True, separators=(',', ':'), default=str).encode())


def source_sha() -> str:
    return sha_bytes(SOURCE.read_bytes())


def atomic_json(path: Path, obj) -> None:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + '.tmp')
    with tmp.open('w') as fh:
        json.dump(obj, fh, indent=1, sort_keys=True, default=str)
        fh.flush(); os.fsync(fh.fileno())
    os.replace(tmp, path)


def atomic_gzip_json(path: Path, obj) -> None:
    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + '.tmp')
    with gzip.open(tmp, 'wt') as fh:
        json.dump(obj, fh, separators=(',', ':'), default=str)
    os.replace(tmp, path)


def load_gzip_json(path: Path):
    with gzip.open(path, 'rt') as fh:
        return json.load(fh)


def atomic_pickle_gz(path: Path, obj) -> None:
    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + '.tmp')
    with gzip.open(tmp, 'wb', compresslevel=4) as fh:
        pickle.dump(obj, fh, protocol=pickle.HIGHEST_PROTOCOL)
    os.replace(tmp, path)


def load_pickle_gz(path: Path):
    class _CompatUnpickler(pickle.Unpickler):
        def find_class(self, module, name):
            if module in ('__main__','v45m','v45mod') and name in globals():
                return globals()[name]
            return super().find_class(module, name)
    with gzip.open(path, 'rb') as fh:
        return _CompatUnpickler(fh).load()


