def interval(vals):
    v = [float(x) for x in vals if x is not None and math.isfinite(float(x))]
    n = len(v)
    if not v:
        return {'n': 0, 'mean': None, 'low': None, 'high': None}
    mean = statistics.mean(v)
    if n < 2:
        return {'n': n, 'mean': mean, 'low': None, 'high': None}
    if student_t is not None:
        q = float(student_t.ppf(.975, n - 1))
    else:
        q = {1:12.706,2:4.303,3:3.182,4:2.776,5:2.571,6:2.447,
             7:2.365,8:2.306,9:2.262,10:2.228,11:2.201,12:2.179,
             13:2.160,14:2.145,15:2.131}.get(n - 1, 1.96)
    half = q * statistics.stdev(v) / math.sqrt(n)
    return {'n': n, 'mean': mean, 'low': mean - half, 'high': mean + half}


def paired(records, left, right, key, load=PRIMARY_LOAD):
    by = collections.defaultdict(dict)
    for r in records:
        if int(r['load']) == int(load):
            by[int(r['seed'])][r['arm']] = r
    diffs = []
    for seed in sorted(by):
        a, b = by[seed].get(left), by[seed].get(right)
        if a is not None and b is not None and a.get(key) is not None and b.get(key) is not None:
            diffs.append(float(a[key]) - float(b[key]))
    return interval(diffs)


def current_rss_bytes() -> int:
    # macOS reports ru_maxrss in bytes; Linux reports KiB. This runner targets macOS,
    # but keep the result sane when self-tested elsewhere.
    r = int(resource.getrusage(resource.RUSAGE_SELF).ru_maxrss)
    if sys.platform.startswith('darwin'):
        return r
    return r * 1024


# -----------------------------------------------------------------------------
# Representation and stream
# -----------------------------------------------------------------------------

def surface_context(key: bytes, wrapper: int) -> bytes:
    w = int(wrapper)
    k = bytearray(key)
    m = KEY_XOR_MASKS[w]
    k[0] ^= m[0]; k[1] ^= m[1]
    c = PREFIX + HEADERS[w] + bytes(k) + SEPARATORS[w]
    if len(c) != 12:
        raise AssertionError('context length')
    return c


def raw_rep(c: bytes) -> np.ndarray:
    a = np.frombuffer(bytes(c)[-12:], dtype=np.uint8)
    if len(a) != 12:
        raise ValueError('distributed representation requires exactly 12 context bytes')
    a = PERMUTATION[a]
    z = BIT_CODE[a].ravel()
    n = float(np.linalg.norm(z))
    return z / n if n > 1e-12 else z


def clean_rep(c: bytes, U: np.ndarray | None) -> np.ndarray:
    z = raw_rep(c)
    if U is not None and np.any(U):
        z = z - U.T @ (U @ z)
    n = float(np.linalg.norm(z))
    return z / n if n > 1e-12 else z


@dataclass
class IdentitySet:
    keys: list[bytes]
    targets: np.ndarray
    conflicts: set[int]


def make_dev_identities(seed: int, n: int, smoke=False) -> IdentitySet:
    # Match Candidate C's generator and conflict discipline.
    ids = CAND_C.make_identities(seed + 1, n, CONFLICT_FRACTION)
    return IdentitySet(list(ids.keys), np.asarray(ids.targets, dtype=np.int64), set(ids.conflicts))


def dev_target(ids: IdentitySet, i: int, wrapper: int) -> int:
    y = int(ids.targets[i])
    if i in ids.conflicts and int(wrapper) == 3:
        return (y + 1 + (int(i) % 251)) % 256
    return y


def make_persistent_stream(seed: int, load: int, exclude_keys=(), repeats=REPEATS,
                           smoke=False):
    rr = np.random.default_rng(seed + 810007)
    count = 4 if smoke else int(load) // 4
    reps = 2 if smoke else int(repeats)
    waves = 4
    alphabet = np.frombuffer(b'0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ', dtype=np.uint8)
    used = set(exclude_keys)
    keys = []
    while len(keys) < count * waves:
        k = bytes(rr.choice(alphabet, size=6))
        if k not in used:
            used.add(k); keys.append(k)
    labels = rr.choice(np.frombuffer(b'abcdefghijklmnopqrstuvwx', dtype=np.uint8),
                       size=len(keys)).astype(int)
    nrev = max(1, count // 4)
    revised = list(range(nrev))
    noisy = list(range(nrev, 2 * nrev))
    untouched = list(range(2 * nrev, count))
    changed = {i: int(ord('a') + (int(labels[i]) - ord('a') + 1 + int(rr.integers(23))) % 24)
               for i in revised}
    rows, checkpoints = [], []

    def add(i, target, kind, exposure, wave, wrapper):
        raw = surface_context(keys[i], wrapper) + bytes([int(target)]) + b'\n'
        if len(raw) != 14:
            raise AssertionError('record length')
        rows.append({'key_id': int(i), 'target': int(target), 'kind': kind,
                     'exposure': int(exposure), 'wave': wave, 'wrapper': int(wrapper),
                     'raw': raw})

    for w in range(waves):
        cohort = chr(65 + w)
        start, end = w * count, (w + 1) * count
        for ex in range(1, reps + 1):
            for i in rr.permutation(np.arange(start, end)):
                add(int(i), int(labels[i]), 'acquisition', ex, cohort, (ex - 1) % 2)
            if ex in tuple(x for x in (1,2,4,8) if x <= reps):
                checkpoints.append({'record_count': len(rows), 'name': f'{cohort}_acq_{ex}',
                                    'type': 'acquisition', 'wave': cohort, 'exposure': ex})
        checkpoints.append({'record_count': len(rows), 'name': f'after_{cohort}',
                            'type': 'wave', 'wave': cohort})
        if w == 1:
            for i in noisy:
                wrong = ord('a') + (int(labels[i]) - ord('a') + 1) % 24
                add(i, wrong, 'one_off_noise', 1, cohort, 0)
        if w == 2:
            for ex in range(1, 3 if smoke else 9):
                for i in rr.permutation(revised):
                    add(int(i), changed[int(i)], 'revision', ex, cohort, 0)
                if ex in (1,2,4,8):
                    checkpoints.append({'record_count': len(rows), 'name': f'revision_{ex}',
                                        'type': 'revision', 'wave': cohort, 'exposure': ex})
    raw = b''.join(r['raw'] for r in rows)
    return {
        'seed': seed, 'load': int(load), 'keys': keys, 'labels': labels,
        'revised': revised, 'noisy': noisy, 'untouched': untouched,
        'revisions': changed, 'rows': rows, 'raw': raw,
        'checkpoints': checkpoints, 'keys_per_wave': count, 'repeats': reps,
        'raw_sha256': sha_bytes(raw),
    }


