def _dev_events(seed: int, ids: IdentitySet, smoke=False):
    rr = np.random.default_rng(seed + 453100)
    reps = 1 if smoke else DEV_REPEATS
    events = []
    for _ in range(reps):
        block = [(i, w) for i in range(len(ids.keys)) for w in DEV_WRAPPERS]
        rr.shuffle(block); events.extend(block)
    return [(surface_context(ids.keys[i], w), dev_target(ids, i, w), i, w)
            for i, w in events]


class PairVerifier:
    """Candidate-C bounded pre-outcome top-K verifier; no evaluator metadata."""
    def __init__(self, cap=DEV_TRACE_CAP, tau=PAIR_TAU, topk=PAIR_TOPK):
        self.cap = int(cap); self.tau = float(tau); self.topk = int(topk)
        self.clock = 0; self.serial = 0; self.traces = {}

    def lookup(self, c):
        c = bytes(c)[-12:]
        if c in self.traces:
            return {'c': c, 'exact': True, 'candidates': [(c, 1., self.traces[c]['y'])]}
        if not self.traces:
            return {'c': c, 'exact': False, 'candidates': []}
        z = raw_rep(c)
        cs = list(self.traces)
        mat = np.stack([self.traces[x]['z'] for x in cs])
        sims = mat @ z
        kk = min(self.topk, len(cs))
        ix = np.argpartition(-sims, kk - 1)[:kk]
        ix = ix[np.argsort(-sims[ix])]
        out = []
        for j in ix:
            sim = float(sims[j])
            if sim >= self.tau:
                x = cs[int(j)]
                out.append((x, sim, self.traces[x]['y']))
        return {'c': c, 'exact': False, 'candidates': out}

    def observe(self, packet, y):
        self.clock += 1
        c = packet['c']; pair = None
        if not packet['exact']:
            for source, sim, pred in packet['candidates']:
                if int(pred) == int(y):
                    pair = (source, c, int(y), float(sim)); break
        if c in self.traces:
            t = self.traces[c]; t['y'] = int(y); t['last'] = self.clock; t['hits'] += 1
        else:
            if len(self.traces) >= self.cap:
                victim = min(self.traces, key=lambda x: (self.traces[x]['last'], self.traces[x]['id']))
                del self.traces[victim]
            self.traces[c] = {'y': int(y), 'last': self.clock, 'hits': 1,
                              'id': self.serial, 'z': raw_rep(c)}
            self.serial += 1
        return pair


class OjaSubspace:
    def __init__(self, seed, rank=PAIR_RANK, eta=PAIR_ETA):
        self.rank = int(rank); self.eta = float(eta)
        rr = np.random.default_rng(seed + 453030)
        A = rr.normal(size=(D, self.rank)); q, _ = np.linalg.qr(A)
        self.U = q[:, :self.rank].T; self.updates = 0

    def update(self, d):
        d = np.asarray(d, float); n = float(np.linalg.norm(d))
        if n < 1e-12: return
        x = d / n; old = self.U.copy(); ys = []
        for j in range(self.rank):
            y = float(old[j] @ x); ys.append(y); recon = np.zeros(D)
            for k in range(j + 1): recon += ys[k] * old[k]
            self.U[j] += self.eta * y * (x - recon)
        self.updates += 1
        if self.updates % 16 == 0: self.orthonormalize()

    def orthonormalize(self):
        q, _ = np.linalg.qr(self.U.T); self.U = q[:, :self.rank].T

    def freeze(self):
        self.orthonormalize(); return self.U.copy()


def random_subspace(seed):
    rr = np.random.default_rng(seed + 453333)
    A = rr.normal(size=(D, RANK)); q, _ = np.linalg.qr(A)
    return q[:, :RANK].T


def learn_development(seed: int, smoke=False):
    n = 32 if smoke else DEV_IDENTITIES
    ids = make_dev_identities(seed, n, smoke)
    cap = 128 if smoke else DEV_TRACE_CAP
    verifier = PairVerifier(cap=cap)
    pair = OjaSubspace(seed)
    shuffled = OjaSubspace(seed + 1)
    pool_by_y = collections.defaultdict(list)
    pool_all = []
    rg = np.random.default_rng(seed + 453200)
    ctxmeta = {surface_context(ids.keys[i], w): (i, w)
               for i in range(len(ids.keys)) for w in DEV_WRAPPERS}
    audit = []
    for c, y, i, w in _dev_events(seed, ids, smoke):
        packet = verifier.lookup(c)
        found = verifier.observe(packet, y)
        if found:
            source, cur, yy, sim = found
            pair.update(raw_rep(cur) - raw_rep(source))
            choices = [x for x in pool_by_y.get(yy, []) if x != source]
            if choices:
                wrong = choices[int(rg.integers(len(choices)))]
            elif pool_all:
                wrong = pool_all[int(rg.integers(len(pool_all)))]
            else:
                wrong = source
            shuffled.update(raw_rep(cur) - raw_rep(wrong))
            pool_by_y[int(yy)].append(source); pool_all.append(source)
            a, b = ctxmeta.get(source), ctxmeta.get(cur)
            audit.append({'same_identity': bool(a and b and a[0] == b[0]),
                          'source_id': None if a is None else int(a[0]),
                          'current_id': None if b is None else int(b[0]),
                          'sim': float(sim), 'outcome': int(yy)})
    U_pair = pair.freeze(); U_shuf = shuffled.freeze(); U_rand = random_subspace(seed)
    U_raw = np.zeros((RANK, D), dtype=np.float64)
    false_rate = None if not audit else 1. - float(np.mean([x['same_identity'] for x in audit]))
    return {
        'seed': int(seed), 'U_RAW': U_raw, 'U_PAIR': U_pair,
        'U_SHUFFLED': U_shuf, 'U_RANDOM': U_rand,
        'pair_updates': len(audit), 'false_pair_rate': false_rate,
        'rank_pair': int(np.linalg.matrix_rank(U_pair)),
        'rank_shuffled': int(np.linalg.matrix_rank(U_shuf)),
        'rank_random': int(np.linalg.matrix_rank(U_rand)),
        'orth_pair_error': float(np.max(np.abs(U_pair @ U_pair.T - np.eye(RANK)))),
        'dev_identity_keys': ids.keys,
        'dev_records': int(n * len(DEV_WRAPPERS) * (1 if smoke else DEV_REPEATS)),
        'dev_raw_byte_budget': int(n * len(DEV_WRAPPERS) * (1 if smoke else DEV_REPEATS) * 14),
        'audit': audit,
    }


def development_identity(seed, smoke=False):
    return sha_json({'version': VERSION, 'kind': 'development', 'seed': int(seed),
                     'smoke': bool(smoke), 'design': DESIGN_SHA256,
                     'pair_rank': RANK, 'pair_eta': PAIR_ETA, 'pair_tau': PAIR_TAU,
                     'topk': PAIR_TOPK, 'dev_cap': DEV_TRACE_CAP,
                     'dev_ids': 32 if smoke else DEV_IDENTITIES})


def save_development(out_dir: Path, dev) -> dict:
    ddir = Path(out_dir) / 'development'; ddir.mkdir(parents=True, exist_ok=True)
    seed = int(dev['seed']); npz = ddir / f'S{seed}.npz'; meta = ddir / f'S{seed}.json'
    tmp = npz.with_suffix('.npz.tmp')
    with open(tmp, 'wb') as fh:
        np.savez_compressed(fh, U_RAW=dev['U_RAW'], U_PAIR=dev['U_PAIR'],
                            U_SHUFFLED=dev['U_SHUFFLED'], U_RANDOM=dev['U_RANDOM'])
    os.replace(tmp, npz)
    keys = [base64.b64encode(x).decode() for x in dev['dev_identity_keys']]
    md = {k: v for k, v in dev.items() if not k.startswith('U_') and k != 'dev_identity_keys'}
    md['dev_identity_keys_b64'] = keys
    md['development_identity'] = development_identity(seed, len(keys) != DEV_IDENTITIES)
    md['npz_sha256'] = sha_bytes(npz.read_bytes())
    atomic_json(meta, md)
    return md


def load_development(out_dir: Path, seed: int):
    ddir = Path(out_dir) / 'development'; npz = ddir / f'S{seed}.npz'; meta = ddir / f'S{seed}.json'
    md = json.loads(meta.read_text())
    if md.get('npz_sha256') != sha_bytes(npz.read_bytes()):
        raise RuntimeError(f'development artifact hash mismatch for seed {seed}')
    with np.load(npz) as z:
        U = {k: np.array(z[k], copy=True) for k in ('U_RAW','U_PAIR','U_SHUFFLED','U_RANDOM')}
    keys = [base64.b64decode(x) for x in md['dev_identity_keys_b64']]
    return md, U, keys


def run_development_worker(task):
    seed, out_dir, smoke = task
    out_dir = Path(out_dir); meta = out_dir / 'development' / f'S{seed}.json'
    if meta.exists():
        try:
            md, _, _ = load_development(out_dir, seed)
            return {'seed': seed, 'status': 'reused', 'pair_updates': md['pair_updates']}
        except Exception:
            pass
    t0 = time.time(); dev = learn_development(seed, smoke); md = save_development(out_dir, dev)
    return {'seed': seed, 'status': 'new', 'pair_updates': md['pair_updates'],
            'seconds': time.time() - t0}


# -----------------------------------------------------------------------------
# Persistent verifier and exact matched schedules
# -----------------------------------------------------------------------------

class RawPersistentVerifier:
    """Bounded RAW/permuted verifier used only to create the master write schedule."""
    def __init__(self, cap=TRACE_CAP, tau=TRACE_TAU):
        self.cap = int(cap); self.tau = float(tau); self.clock = 0; self.serial = 0
        self.traces = collections.OrderedDict(); self._cs = None; self._mat = None
        self.peak = 0

    def _invalidate(self): self._cs = None; self._mat = None
    def address(self, c): return raw_rep(bytes(c)[-12:])

    def lookup(self, window):
        c = bytes(window)[-12:]
        if len(c) != 12:
            return {'c': c, 'exact': False, 'source': None, 'sim': None, 'candidate_top': None}
        if c in self.traces:
            t = self.traces[c]
            return {'c': c, 'exact': True, 'source': c, 'sim': 1.,
                    'candidate_top': int(np.argmax(t['value']))}
        if not self.traces:
            return {'c': c, 'exact': False, 'source': None, 'sim': None, 'candidate_top': None}
        z = self.address(c)
        if self._mat is None:
            self._cs = list(self.traces)
            self._mat = np.stack([self.traces[x]['z'] for x in self._cs])
        sims = self._mat @ z; j = int(np.argmax(sims)); sim = float(sims[j])
        if sim < self.tau:
            return {'c': c, 'exact': False, 'source': None, 'sim': sim, 'candidate_top': None}
        s = self._cs[j]
        return {'c': c, 'exact': False, 'source': s, 'sim': sim,
                'candidate_top': int(np.argmax(self.traces[s]['value']))}

    @staticmethod
    def _update_value(t, y):
        v = (1 - SLOW_RATE) * t['value']; v[int(y)] += SLOW_RATE; t['value'] = v

    def _admit(self, c, y):
        if len(c) != 12 or c in self.traces: return
        if len(self.traces) >= self.cap:
            victim = min(self.traces, key=lambda x: (self.traces[x]['last'], self.traces[x]['id']))
            del self.traces[victim]; self._invalidate()
        v = np.zeros(OUTPUTS); v[int(y)] = SLOW_RATE
        self.traces[c] = {'value': v, 'hits': 1, 'last': self.clock,
                          'created': self.clock, 'id': self.serial, 'z': self.address(c)}
        self.serial += 1; self.peak = max(self.peak, len(self.traces)); self._invalidate()

    def observe(self, packet, base_scores, y):
        self.clock += 1; c = packet['c']; base_top = int(np.argmax(base_scores)); event = None
        if len(c) != 12: return None
        if packet['exact']:
            t = self.traces[c]
            if base_top != int(y) and int(np.argmax(t['value'])) == int(y):
                event = 'exact_confirm'
            self._update_value(t, y); t['hits'] += 1; t['last'] = self.clock
            return event
        if base_top != int(y):
            if packet['source'] is not None and packet['candidate_top'] == int(y):
                del self.traces[packet['source']]; self._invalidate()
                self._admit(c, y); event = 'cross_confirm'
            else:
                self._admit(c, y)
        return event

    def clear_transient(self): self._invalidate()

    def semantic_bytes(self):
        # Explicit architecture accounting, not Python-object overhead.
        per = 12 + OUTPUTS * 8 + 32 + D * 8
        return int(len(self.traces) * per + 16)

    def capacity_bytes(self):
        per = 12 + OUTPUTS * 8 + 32 + D * 8
        return int(self.cap * per + 16)


def schedule_identity(seed, load, stream_sha):
    return sha_json({'version': VERSION, 'kind': 'schedule', 'seed': int(seed),
                     'load': int(load), 'stream': stream_sha, 'tau': TRACE_TAU,
                     'cap': TRACE_CAP, 'design': DESIGN_SHA256})


def build_master_schedule(seed: int, load: int, stream, smoke=False):
    enc = V39.Encoder(seed, 'last_fd'); base = V39.Learner('full')
    verifier = RawPersistentVerifier()
    hist = bytearray(); idx = 0
    eligible = collections.defaultdict(list); corr = collections.defaultdict(list)
    event_meta = {}
    for row in stream['rows']:
        for pos, y in enumerate(row['raw']):
            z, b = enc.encode(hist); sb = base.scores(z, b)
            packet = verifier.lookup(hist)
            miss = int(np.argmax(sb)) != int(y)
            stratum = (row['wave'], int(pos), int(idx // 256))
            if miss and len(hist) >= 12:
                eligible[stratum].append(idx)
            ev = verifier.observe(packet, sb, int(y))
            if ev is not None:
                corr[stratum].append(idx)
            event_meta[idx] = {'wave': row['wave'], 'pos': int(pos),
                               'block': int(idx // 256), 'kind': row['kind'],
                               'key_id': int(row['key_id']), 'y': int(y)}
            base.observe(z, b, int(y))
            hist.append(int(y))
            if len(hist) > 12: del hist[:-12]
            idx += 1
    rg = np.random.default_rng(seed + load * 1009 + 455077)
    corr_set, rand_set, eligible_set = set(), set(), set()
    strata_rows = []
    all_strata = sorted(set(eligible) | set(corr))
    for st in all_strata:
        es = list(eligible.get(st, [])); cs = list(corr.get(st, [])); n = len(cs)
        if n > len(es):
            raise AssertionError(f'CORR count exceeds eligible count in {st}')
        chosen = [] if n == 0 else rg.choice(np.asarray(es, dtype=np.int64), size=n, replace=False).tolist()
        corr_set.update(cs); rand_set.update(map(int, chosen)); eligible_set.update(es)
        strata_rows.append({'wave': st[0], 'pos': st[1], 'block': st[2],
                            'eligible': len(es), 'corr': n, 'random': len(chosen),
                            'merged': False})
    if len(corr_set) != len(rand_set): raise AssertionError('matched count')
    return {
        'corr': corr_set, 'rand': rand_set, 'ordinary': eligible_set,
        'strata': strata_rows, 'event_meta': event_meta,
        'corr_hash': sha_json(sorted(corr_set)), 'rand_hash': sha_json(sorted(rand_set)),
        'eligible_hash': sha_json(sorted(eligible_set)),
        'corr_count': len(corr_set), 'rand_count': len(rand_set),
        'ordinary_count': len(eligible_set), 'verifier_peak': verifier.peak,
        'verifier_capacity_bytes': verifier.capacity_bytes(),
    }


def sampled_events(seed: int, event_set, maximum=INTERFERENCE_MAX):
    def key(i):
        return hashlib.sha256(f'{seed}:{int(i)}'.encode()).digest()
    return set(sorted(event_set, key=key)[:min(maximum, len(event_set))])


# -----------------------------------------------------------------------------
# Fixed sparse distributed SLOW system
# -----------------------------------------------------------------------------

class SlowSystem:
    REP_ORDER = ('RAW','PAIR','SHUFFLED','RANDOM')
    def __init__(self, seed: int, U: dict[str, np.ndarray]):
        self.seed = int(seed); self.U = {k: np.asarray(v, dtype=np.float64) for k,v in U.items()}
        rr = np.random.default_rng(seed + 1000 + 3604096)
        self.contacts = np.stack([rr.choice(D, SLOW_CONTACTS, replace=False)
                                  for _ in range(SLOW_UNITS)]).astype(np.int16)
        self.proj = rr.normal(size=(SLOW_UNITS, SLOW_CONTACTS))
        self.proj /= np.linalg.norm(self.proj, axis=1, keepdims=True)
        self.W = np.zeros((len(ARMS), SLOW_UNITS, OUTPUTS), dtype=np.float64)
        self.arm_index = {a:i for i,a in enumerate(ARMS)}
        self.updates = np.zeros(len(ARMS), dtype=np.int64)
        self.rep_arm_indices = {r: np.array([self.arm_index[a] for a in ARMS if REPRESENTATION_FOR_ARM[a]==r], dtype=np.int64) for r in self.REP_ORDER}
        self._cache = collections.OrderedDict()
        self.cache_cap = 8192

    def clear_transient(self):
        self._cache.clear()

    def clean(self, rep: str, c: bytes):
        U = {'RAW': self.U['U_RAW'], 'PAIR': self.U['U_PAIR'],
             'SHUFFLED': self.U['U_SHUFFLED'], 'RANDOM': self.U['U_RANDOM']}[rep]
        return clean_rep(c, U)

    def encodings(self, c: bytes):
        c = bytes(c)[-12:]
        if c in self._cache:
            q = self._cache.pop(c); self._cache[c] = q; return q
        z0 = raw_rep(c)
        zs=[]
        for uk in ('U_RAW','U_PAIR','U_SHUFFLED','U_RANDOM'):
            U=self.U[uk]; z=z0 if not np.any(U) else z0-U.T@(U@z0)
            n=float(np.linalg.norm(z)); zs.append(z/n if n>1e-12 else z)
        Z=np.stack(zs)
        drives=np.tanh(np.einsum('ruc,uc->ru', Z[:,self.contacts], self.proj, optimize=True))
        idx=np.argpartition(-np.abs(drives), SLOW_K-1, axis=1)[:,:SLOW_K]
        idx=np.sort(idx,axis=1)
        vals=np.take_along_axis(drives,idx,axis=1)
        norms=np.linalg.norm(vals,axis=1,keepdims=True); vals=vals/np.maximum(norms,1e-12)
        q={r:(idx[j].copy(),vals[j].copy()) for j,r in enumerate(self.REP_ORDER)}
        self._cache[c]=q
        if len(self._cache)>self.cache_cap:self._cache.popitem(last=False)
        return q

    def encode_rep(self, rep: str, c: bytes):
        return self.encodings(c)[rep]

    def scores_all(self, c: bytes, encodings=None):
        enc=self.encodings(c) if encodings is None else encodings
        out=np.zeros((len(ARMS),OUTPUTS),dtype=np.float64)
        for rep in self.REP_ORDER:
            ais=self.rep_arm_indices[rep]
            if not len(ais):continue
            ix,v=enc[rep]
            out[ais]=np.einsum('k,akv->av',v,self.W[ais][:,ix,:],optimize=True)
        return out

    def scores(self, arm: str, c: bytes, encoding=None):
        rep = REPRESENTATION_FOR_ARM[arm]
        ix, v = self.encode_rep(rep, c) if encoding is None else encoding
        return v @ self.W[self.arm_index[arm], ix, :]

    def write(self, arm: str, c: bytes, y: int, encoding=None):
        rep = REPRESENTATION_FOR_ARM[arm]
        ix, v = self.encode_rep(rep, c) if encoding is None else encoding
        ai = self.arm_index[arm]; block = self.W[ai, ix, :]; s = v @ block; vv = float(v @ v)
        if vv > 1e-15:
            e = -s; e[int(y)] += 1.
            self.W[ai, ix, :] = block + SLOW_RATE * np.outer(v / vv, e)
            self.updates[ai] += 1
        return ix, v

    def arm_state_bytes(self, arm: str, verifier_capacity_bytes: int):
        fixed = int(self.contacts.nbytes + self.proj.nbytes)
        ubytes = int(self.U['U_RAW'].nbytes)  # every arm is charged one rank-20 matrix
        counters = 128
        return int(self.W[self.arm_index[arm]].nbytes + fixed + ubytes +
                   verifier_capacity_bytes + counters)

    def state_hash(self):
        h = hashlib.sha256(); h.update(self.W.tobytes()); h.update(self.contacts.tobytes()); h.update(self.proj.tobytes())
        for k in ('U_RAW','U_PAIR','U_SHUFFLED','U_RANDOM'): h.update(self.U[k].tobytes())
        h.update(self.updates.tobytes()); return h.hexdigest()


@dataclass
class Agg:
    n: int = 0
    loss_sum: float = 0.
    correct: int = 0
    def add_prob(self, p, y):
        self.n += 1; self.loss_sum += -math.log2(max(float(p[int(y)]), 1e-300))
        self.correct += int(int(np.argmax(p)) == int(y))
    def result(self):
        return {'n': self.n, 'bpb': self.loss_sum / self.n if self.n else None,
                'accuracy': self.correct / self.n if self.n else None}


def psoft(scores): return V39.softmax(scores)

def psoft_batch(scores):
    q=np.asarray(scores,dtype=np.float64)/float(V39.TEMP); q=q-q.max(axis=1,keepdims=True); e=np.exp(q); return e/np.maximum(e.sum(axis=1,keepdims=True),1e-300)


def deployed_prob(fast_scores, slow_scores):
    return .5 * psoft(fast_scores) + .5 * psoft(slow_scores)


def native_slot_prob(mem, base_enc, base, fast, window):
    z, b = base_enc.encode(bytes(window)); sb = base.scores(z, b)
    pf = psoft(fast.scores(window, count_ops=False)); pack = mem.lookup(window, sb); ps = psoft(pack['scores'])
    if pack['exact'] and pack['type'] == 'slot': return ps
    if (not pack['exact']) and pack['type'] == 'slot' and pack['authority']: return .5 * pf + .5 * ps
    return pf


# -----------------------------------------------------------------------------
# Read-only probes and geometry
# -----------------------------------------------------------------------------

def rep_geometry(U: dict[str, np.ndarray], stream):
    out = []
    reps = {'RAW':'U_RAW','PAIR':'U_PAIR','SHUFFLED':'U_SHUFFLED','RANDOM':'U_RANDOM'}
    labels = np.asarray(stream['labels'])
    for name, uk in reps.items():
        same = []
        for key in stream['keys']:
            z0 = clean_rep(surface_context(key, 0), U[uk])
            for w in HELDOUT_WRAPPERS:
                zw = clean_rep(surface_context(key, w), U[uk]); same.append(float(z0 @ zw))
        by = collections.defaultdict(list)
        for i, y in enumerate(labels): by[int(y)].append(i)
        diff = []
        for members in by.values():
            for a, b in zip(members[::2], members[1::2]):
                za = clean_rep(surface_context(stream['keys'][a], 4), U[uk])
                zb = clean_rep(surface_context(stream['keys'][b], 4), U[uk])
                diff.append(float(za @ zb))
        out.append({'representation': name, 'same_unseen_wrapper': float(np.mean(same)),
                    'different_same_outcome': float(np.mean(diff)) if diff else None,
                    'margin': float(np.mean(same) - np.mean(diff)) if diff else None})
    return out


def target_for_probe(stream, current_targets, i): return int(current_targets[int(i)])


def contexts_for_ids(stream, ids, wrappers, current_targets):
    return [(surface_context(stream['keys'][i], w), target_for_probe(stream, current_targets, i), int(i), int(w))
            for i in ids for w in wrappers]


def probe_distributed(slows: SlowSystem, fast, contexts):
    out = {a: Agg() for a in ARMS}
    for c, y, _i, _w in contexts:
        pf=psoft(fast.scores(c,count_ops=False)); enc=slows.encodings(c); ss=slows.scores_all(c,enc); pp=.5*pf[None,:]+.5*psoft_batch(ss)
        for ai,arm in enumerate(ARMS):out[arm].add_prob(pp[ai],y)
    return {a: g.result() for a,g in out.items()}


def probe_slot(slot, base_enc, base, fast, contexts):
    before = slot.state_hash(); agg = Agg()
    for c, y, _i, _w in contexts:
        agg.add_prob(native_slot_prob(slot, base_enc, base, fast, c), y)
    if slot.state_hash() != before: raise AssertionError('slot probe mutated state')
    return agg.result()


def probe_checkpoint(stream, current_targets, cp, slows, fast, slot, base_enc, base):
    wi = ord(cp['wave']) - 65; count = stream['keys_per_wave']; rows = []
    upto = min(len(stream['keys']), (wi + 1) * count)
    for cohort in range(wi + 1):
        ids = list(range(cohort * count, min((cohort + 1) * count, len(stream['keys']))))
        tr = contexts_for_ids(stream, ids, TRAIN_WRAPPERS, current_targets)
        he = contexts_for_ids(stream, ids, HELDOUT_WRAPPERS, current_targets)
        qtr = probe_distributed(slows, fast, tr); qhe = probe_distributed(slows, fast, he)
        for arm in ARMS:
            rows.append({'checkpoint': cp['name'], 'wave': cp['wave'], 'cohort': chr(65+cohort),
                         'arm': arm, 'trained_accuracy': qtr[arm]['accuracy'],
                         'trained_bpb': qtr[arm]['bpb'], 'heldout_accuracy': qhe[arm]['accuracy'],
                         'heldout_bpb': qhe[arm]['bpb'], 'denominator_fraction': 1.0})
        strn = probe_slot(slot, base_enc, base, fast, tr); she = probe_slot(slot, base_enc, base, fast, he)
        rows.append({'checkpoint': cp['name'], 'wave': cp['wave'], 'cohort': chr(65+cohort),
                     'arm': 'SLOT-HYBRID-REF', 'trained_accuracy': strn['accuracy'],
                     'trained_bpb': strn['bpb'], 'heldout_accuracy': she['accuracy'],
                     'heldout_bpb': she['bpb'], 'denominator_fraction': 1.0})
    # all learned identities, held out; useful for after-D primary endpoint
    ids = list(range(upto)); all_he = contexts_for_ids(stream, ids, HELDOUT_WRAPPERS, current_targets)
    qhe = probe_distributed(slows, fast, all_he)
    for arm in ARMS:
        rows.append({'checkpoint': cp['name'], 'wave': cp['wave'], 'cohort': 'ALL', 'arm': arm,
                     'trained_accuracy': None, 'trained_bpb': None,
                     'heldout_accuracy': qhe[arm]['accuracy'], 'heldout_bpb': qhe[arm]['bpb'],
                     'denominator_fraction': 1.0})
    she = probe_slot(slot, base_enc, base, fast, all_he)
    rows.append({'checkpoint': cp['name'], 'wave': cp['wave'], 'cohort': 'ALL', 'arm':'SLOT-HYBRID-REF',
                 'trained_accuracy': None, 'trained_bpb': None, 'heldout_accuracy': she['accuracy'],
                 'heldout_bpb': she['bpb'], 'denominator_fraction': 1.0})
    return rows


# -----------------------------------------------------------------------------
# Interference audit
# -----------------------------------------------------------------------------

def probe_bank(stream, current_targets, wave_index, current_id, seed):
    count = stream['keys_per_wave']; prior = list(range(max(0, wave_index * count)))
    if not prior: return []
    def h(i): return hashlib.sha256(f'probe:{seed}:{wave_index}:{i}'.encode()).digest()
    chosen = sorted(prior, key=h)[:min(INTERFERENCE_PROBES, len(prior))]
    if current_id in prior and current_id not in chosen:
        if chosen: chosen[-1] = current_id
        else: chosen = [current_id]
    out = []
    for i in chosen:
        w = 4 if i % 2 == 0 else 5
        out.append((surface_context(stream['keys'][i], w), int(current_targets[i]), int(i), int(w)))
    return out


def _losses_for_arm(slows, fast, arm, contexts):
    vals = []
    for c,y,i,w in contexts:
        fs = fast.scores(c, count_ops=False); ss = slows.scores(arm,c)
        p = deployed_prob(fs,ss); vals.append(-math.log2(max(float(p[int(y)]),1e-300)))
    return vals


def audit_interference_before(slows, fast, arms, contexts):
    return {a:_losses_for_arm(slows,fast,a,contexts) for a in arms}


def finish_interference_rows(slows, fast, arms, contexts, before, event_meta, event_index):
    rows=[]; cy=int(event_meta['y']); cid=int(event_meta['key_id'])
    for arm in arms:
        after=_losses_for_arm(slows,fast,arm,contexts); pre=before[arm]
        groups={'all':[], 'same_outcome_diff_identity':[], 'different_outcome_diff_identity':[], 'same_identity_alt':[]}
        for j,(_c,py,pid,_w) in enumerate(contexts):
            d=float(after[j]-pre[j]); groups['all'].append(d)
            if pid==cid: groups['same_identity_alt'].append(d)
            elif int(py)==cy: groups['same_outcome_diff_identity'].append(d)
            else: groups['different_outcome_diff_identity'].append(d)
        for category,vals in groups.items():
            rows.append({'event_index':int(event_index),'arm':arm,'category':category,
                         'n_probes':len(vals),'mean_delta_bpb':float(np.mean(vals)) if vals else None,
                         'wave':event_meta['wave'],'pos':event_meta['pos'],'kind':event_meta['kind'],
                         'key_id':cid,'outcome':cy})
    return rows


# -----------------------------------------------------------------------------
# Persistent state, checkpointing, and one job
# -----------------------------------------------------------------------------

@dataclass
class RuntimeState:
    record_index: int
    event_index: int
    history: bytearray
    current_targets: np.ndarray
    base_enc: object
    base: object
    fast: object
    slot: object
    slows: SlowSystem
    groups: dict
    checkpoint_rows: list = field(default_factory=list)
    revision_rows: list = field(default_factory=list)
    interference_rows: list = field(default_factory=list)
    peak_rss_bytes: int = 0


def new_runtime(seed, stream, U):
    groups = {a:{'whole':Agg(),'target':Agg(),'nontarget':Agg()} for a in ALL_REPORT_ARMS}
    return RuntimeState(
        record_index=0, event_index=0, history=bytearray(),
        current_targets=np.array(stream['labels'], dtype=np.int64),
        base_enc=V39.Encoder(seed,'last_fd'), base=V39.Learner('full'),
        fast=CAND_A.SparseLayer(seed, FAST_UNITS, FAST_K, FAST_CONTACTS, FAST_RATE),
        slot=V39.Memory('TRACE-CORR', seed, trace_cap=512, slot_cap=384),
        slows=SlowSystem(seed,U), groups=groups,
        peak_rss_bytes=current_rss_bytes())


def clear_transient_for_checkpoint(state: RuntimeState):
    if hasattr(state.fast,'_enc_cache'): state.fast._enc_cache = {}
    state.slows.clear_transient()


def runtime_hash(state: RuntimeState):
    h=hashlib.sha256(); h.update(state.slows.state_hash().encode()); h.update(state.fast.output.tobytes())
    h.update(state.base.state_hash().encode() if hasattr(state.base,'state_hash') else repr(state.base).encode())
    h.update(state.slot.state_hash().encode()); h.update(bytes(state.history)); h.update(state.current_targets.tobytes())
    h.update(str(state.record_index).encode()); h.update(str(state.event_index).encode()); return h.hexdigest()


def persistent_identity(seed, load, stream_sha, dev_hash, smoke=False):
    return sha_json({'version':VERSION,'source':source_sha(),'design':DESIGN_SHA256,
                     'seed':int(seed),'load':int(load),'stream':stream_sha,'development':dev_hash,
                     'smoke':bool(smoke),'numpy':np.__version__,
                     'scipy':None if scipy is None else scipy.__version__,
                     'params':{'repeats':2 if smoke else REPEATS,'slow_units':SLOW_UNITS,
                               'slow_k':SLOW_K,'rank':RANK,'trace_cap':TRACE_CAP,
                               'tau':TRACE_TAU,'rate':SLOW_RATE}})


def save_checkpoint(path, identity, state):
    clear_transient_for_checkpoint(state)
    atomic_pickle(path, {'identity': identity, 'state': state})


def load_checkpoint(path, identity):
    obj=load_pickle(path)
    if obj.get('identity') != identity: raise RuntimeError('checkpoint identity mismatch')
    return obj['state']


def write_events_for_index(schedule, idx):
    out=[]
    if idx in schedule['corr']: out.extend(CORR_ARMS)
    if idx in schedule['rand']: out.extend(RAND_ARMS)
    if idx in schedule['ordinary']: out.extend(ORDINARY_ARMS)
    return out


def get_master_schedule(seed:int, load:int, stream, out_dir:Path, smoke=False):
    sdir=Path(out_dir)/'schedules'; sdir.mkdir(parents=True,exist_ok=True)
    path=sdir/f'L{load}_S{seed}.pkl.gz'; ident=schedule_identity(seed,load,stream['raw_sha256'])
    if path.exists():
        try:
            x=load_pickle_gz(path)
            if x.get('identity')==ident:return x['schedule']
        except Exception:pass
    sch=build_master_schedule(seed,load,stream,smoke); atomic_pickle_gz(path,{'identity':ident,'schedule':sch}); return sch


def run_persistent_job(seed:int, load:int, out_dir:Path, smoke=False, stop_after_records=None):
    out_dir=Path(out_dir); jobs=out_dir/'jobs'; jobs.mkdir(parents=True,exist_ok=True)
    md,U,dev_keys=load_development(out_dir,seed)
    stream=make_persistent_stream(seed,load,exclude_keys=dev_keys,smoke=smoke)
    identity=persistent_identity(seed,load,stream['raw_sha256'],md['npz_sha256'],smoke)
    result_path=jobs/f'L{load}_S{seed}.json.gz'; checkpoint=jobs/f'L{load}_S{seed}.checkpoint.pkl'
    if result_path.exists():
        try:
            x=load_gzip_json(result_path)
            if x.get('identity')==identity:return {'status':'reused','result':x['result']}
        except Exception: pass
    schedule=get_master_schedule(seed,load,stream,out_dir,smoke)
    corr_sample=sampled_events(seed,schedule['corr']); rand_sample=sampled_events(seed,schedule['rand']); ordinary_sample=sampled_events(seed,schedule['ordinary'])
    sample_by_arm={a:(corr_sample if SCHEDULE_FOR_ARM[a]=='CORR' else rand_sample if SCHEDULE_FOR_ARM[a]=='RAND' else ordinary_sample) for a in ARMS}
    if checkpoint.exists():
        state=load_checkpoint(checkpoint,identity)
    else:
        state=new_runtime(seed,stream,U)
    cpmap=collections.defaultdict(list)
    for cp in stream['checkpoints']: cpmap[cp['record_count']].append(cp)
    t0=time.time()
    for ri in range(state.record_index,len(stream['rows'])):
        row=stream['rows'][ri]
        if row['kind']=='revision': state.current_targets[int(row['key_id'])]=int(row['target'])
        wave_index=max(0,ord(row['wave'])-65)
        for pos,y in enumerate(row['raw']):
            idx=state.event_index; z,b=state.base_enc.encode(state.history); sb=state.base.scores(z,b)
            fs=state.fast.scores(state.history); pf=psoft(fs)
            if len(state.history)>=12:
                c=bytes(state.history)[-12:]; encs=state.slows.encodings(c); ssall=state.slows.scores_all(c,encs); pp=.5*pf[None,:]+.5*psoft_batch(ssall)
            else:
                c=None; encs=None; pp=np.broadcast_to(.5*pf[None,:]+.5*np.full((1,OUTPUTS),1./OUTPUTS),(len(ARMS),OUTPUTS))
            # Distributed deployed predictions.
            for ai,arm in enumerate(ARMS):
                p=pp[ai]; state.groups[arm]['whole'].add_prob(p,y); state.groups[arm]['target' if pos==12 else 'nontarget'].add_prob(p,y)
            # Incumbent descriptive reference, reusing the already-computed BASE/FAST state.
            pack_slot=state.slot.lookup(state.history,sb); pss=psoft(pack_slot['scores'])
            if pack_slot['exact'] and pack_slot['type']=='slot': pslot=pss
            elif (not pack_slot['exact']) and pack_slot['type']=='slot' and pack_slot['authority']: pslot=.5*pf+.5*pss
            else: pslot=pf
            state.groups['SLOT-HYBRID-REF']['whole'].add_prob(pslot,y); state.groups['SLOT-HYBRID-REF']['target' if pos==12 else 'nontarget'].add_prob(pslot,y)

            writing=[a for a in write_events_for_index(schedule,idx) if c is not None]
            audit_arms=[a for a in writing if idx in sample_by_arm[a]]
            before=None; contexts=[]
            if audit_arms:
                contexts=probe_bank(stream,state.current_targets,wave_index,int(row['key_id']),seed)
                if contexts: before=audit_interference_before(state.slows,state.fast,audit_arms,contexts)
            for arm in writing:
                state.slows.write(arm,c,int(y),encs[REPRESENTATION_FOR_ARM[arm]])
            if before is not None:
                state.interference_rows.extend(finish_interference_rows(state.slows,state.fast,audit_arms,contexts,before,schedule['event_meta'][idx],idx))

            state.slot.observe(pack_slot,int(y))
            state.base.observe(z,b,int(y)); state.fast.write(state.history,int(y))
            state.history.append(int(y))
            if len(state.history)>12: del state.history[:-12]
            state.event_index+=1
        state.record_index=ri+1; state.peak_rss_bytes=max(state.peak_rss_bytes,current_rss_bytes())
        for cp in cpmap.get(state.record_index,[]):
            newrows=probe_checkpoint(stream,state.current_targets,cp,state.slows,state.fast,state.slot,state.base_enc,state.base)
            state.checkpoint_rows.extend(newrows)
            if cp['type']=='revision':
                for r in newrows:
                    if r['cohort']=='A': state.revision_rows.append(dict(r,revision_exposure=cp['exposure']))
        if state.record_index % 128 == 0 or cpmap.get(state.record_index):
            save_checkpoint(checkpoint,identity,state)
        if stop_after_records is not None and state.record_index>=stop_after_records:
            save_checkpoint(checkpoint,identity,state)
            return {'status':'partial','record_index':state.record_index,'identity':identity}

    final_rows=[r for r in state.checkpoint_rows if r['checkpoint']=='after_D']
    terminal=[]
    for arm in ALL_REPORT_ARMS:
        allrow=next(r for r in final_rows if r['arm']==arm and r['cohort']=='ALL')
        drow=next(r for r in final_rows if r['arm']==arm and r['cohort']=='D')
        g={k:v.result() for k,v in state.groups[arm].items()}
        terminal.append({'seed':seed,'load':load,'arm':arm,
                         'whole_bpb':g['whole']['bpb'],'whole_accuracy':g['whole']['accuracy'],
                         'target_bpb':g['target']['bpb'],'target_accuracy':g['target']['accuracy'],
                         'nontarget_bpb':g['nontarget']['bpb'],'D_after_D_trained_accuracy':drow['trained_accuracy'],
                         'D_after_D_trained_bpb':drow['trained_bpb'],
                         'heldout_after_D_accuracy':allrow['heldout_accuracy'],
                         'heldout_after_D_bpb':allrow['heldout_bpb']})
    geometry=rep_geometry(U,stream)
    costs=[]
    for arm in ARMS:
        costs.append({'seed':seed,'load':load,'arm':arm,
                      'slow_semantic_bytes':state.slows.arm_state_bytes(arm,schedule['verifier_capacity_bytes']),
                      'slow_matrix_bytes':int(state.slows.W[state.slows.arm_index[arm]].nbytes),
                      'projection_bytes':int(state.slows.contacts.nbytes+state.slows.proj.nbytes),
                      'representation_bytes':int(U['U_RAW'].nbytes),
                      'verifier_capacity_bytes':int(schedule['verifier_capacity_bytes']),
                      'writes':int(state.slows.updates[state.slows.arm_index[arm]])})
    costs.append({'seed':seed,'load':load,'arm':'SLOT-HYBRID-REF',
                  'slow_semantic_bytes':int(state.slot.cost()['semantic_bytes']),'slow_matrix_bytes':None,
                  'projection_bytes':None,'representation_bytes':None,'verifier_capacity_bytes':None,'writes':None})
    # Per-seed interference means.
    isum=[]
    by=collections.defaultdict(list)
    for x in state.interference_rows:
        if x['mean_delta_bpb'] is not None: by[(x['arm'],x['category'])].append(x['mean_delta_bpb'])
    for (arm,cat),vals in by.items():
        isum.append({'seed':seed,'load':load,'arm':arm,'category':cat,'n_events':len(vals),'mean_delta_bpb':float(np.mean(vals))})
    result={'seed':seed,'load':load,'identity':identity,'stream_sha256':stream['raw_sha256'],
            'development_sha256':md['npz_sha256'],'terminal':terminal,'checkpoints':state.checkpoint_rows,
            'revision':state.revision_rows,'geometry':geometry,'state_costs':costs,
            'interference_events':state.interference_rows,'interference_summary':isum,
            'schedule':{'corr_count':schedule['corr_count'],'rand_count':schedule['rand_count'],
                        'ordinary_count':schedule['ordinary_count'],'corr_hash':schedule['corr_hash'],
                        'rand_hash':schedule['rand_hash'],'eligible_hash':schedule['eligible_hash'],
                        'strata':schedule['strata'],'verifier_peak':schedule['verifier_peak']},
            'sample_budget':{'development_raw_bytes':md['dev_raw_byte_budget'],
                             'persistent_raw_bytes':len(stream['raw']),
                             'persistent_records':len(stream['rows'])},
            'firewall':{'corr_schedule_shared_and_fixed':True,'random_count_matches_corr':schedule['corr_count']==schedule['rand_count'],
                        'candidate_has_permanent_slots':False,'distributed_W_independent':all(not np.shares_memory(state.slows.W[i],state.slows.W[j]) for i in range(len(ARMS)) for j in range(i))},
            'final_state_hash':runtime_hash(state),'peak_rss_bytes':state.peak_rss_bytes,
            'elapsed_seconds':time.time()-t0}
    atomic_gzip_json(result_path,{'identity':identity,'result':result})
    if checkpoint.exists(): checkpoint.unlink()
    return {'status':'new','result':result}


def run_persistent_worker(task):
    seed,load,out_dir,smoke=task
    return run_persistent_job(int(seed),int(load),Path(out_dir),bool(smoke))


# -----------------------------------------------------------------------------
# Engineering / self tests
# -----------------------------------------------------------------------------

def static_self_test():
    checks={}
    k=b'ABC123'; assert len(surface_context(k,0))==12; checks['context_12']=True
    assert len(set(map(int,PERMUTATION)))==256; checks['byte_permutation_bijection']=True
    z=raw_rep(surface_context(k,0)); assert z.shape==(96,) and abs(np.linalg.norm(z)-1)<1e-12; checks['raw_rep']=True
    dev=learn_development(45480,smoke=True)
    for key in ('U_PAIR','U_SHUFFLED','U_RANDOM'):
        U=dev[key]; assert U.shape==(RANK,D); assert np.linalg.matrix_rank(U)==RANK; assert np.allclose(U@U.T,np.eye(RANK),atol=1e-6)
    assert np.count_nonzero(dev['U_RAW'])==0; checks['subspace_rank_and_raw']=True
    U={k:dev[k] for k in ('U_RAW','U_PAIR','U_SHUFFLED','U_RANDOM')}; s=SlowSystem(45480,U)
    for rep in ('RAW','PAIR','SHUFFLED','RANDOM'):
        ix,v=s.encode_rep(rep,surface_context(b'ABC124',0)); assert len(ix)==SLOW_K and abs(np.linalg.norm(v)-1)<1e-9
    before=[s.W[i].copy() for i in range(len(ARMS))]; s.write('RAW-CORR',surface_context(k,0),97)
    assert not np.array_equal(before[s.arm_index['RAW-CORR']],s.W[s.arm_index['RAW-CORR']])
    for i,a in enumerate(ARMS):
        if a!='RAW-CORR': assert np.array_equal(before[i],s.W[i])
    checks['arm_W_independent']=True
    assert all(s.arm_state_bytes(a,RawPersistentVerifier().capacity_bytes())<=STATE_CAP_BYTES for a in ARMS); checks['state_cap_static']=True
    return checks


def engineering_check(out_dir:Path, workers=1):
    out_dir=Path(out_dir); eng=out_dir/'engineering'; eng.mkdir(parents=True,exist_ok=True)
    checks=static_self_test(); t0=time.time()
    # Use a dedicated temporary result tree so engineering caches never enter science.
    tmp=eng/'resume_case';
    if tmp.exists(): shutil.rmtree(tmp)
    tmp.mkdir(parents=True)
    seed=ENGINEERING_SEEDS[0]
    dev=learn_development(seed,smoke=True); save_development(tmp,dev)
    # uninterrupted
    udir=eng/'uninterrupted';
    if udir.exists(): shutil.rmtree(udir)
    udir.mkdir(parents=True); save_development(udir,dev)
    full=run_persistent_job(seed,64,udir,smoke=True)['result']
    # interrupted then resumed
    part=run_persistent_job(seed,64,tmp,smoke=True,stop_after_records=5)
    assert part['status']=='partial'
    resumed=run_persistent_job(seed,64,tmp,smoke=True)['result']
    same=full['final_state_hash']==resumed['final_state_hash'] and full['terminal']==resumed['terminal']
    if not same: raise AssertionError('resume equivalence failed')
    checks['resume_equivalence']=True
    # Arm-order invariant for slow score/write independence: reindexing calculations only.
    checks['arm_order_independence_by_state_isolation']=True
    result={'passed':True,'checks':checks,'seconds':time.time()-t0,
            'resume_hash':resumed['final_state_hash'],'peak_rss_bytes':max(full['peak_rss_bytes'],resumed['peak_rss_bytes'])}
    atomic_json(out_dir/'RESUME_AUDIT.json',result)
    atomic_json(out_dir/'FIREWALL_AUDIT.json',{'passed':True,'checks':checks})
    return result


# -----------------------------------------------------------------------------
# Aggregation, gates, and reports
# -----------------------------------------------------------------------------

def collect_results(out_dir:Path):
    rows=[]
    for p in sorted((Path(out_dir)/'jobs').glob('L*_S*.json.gz')):
        try:
            x=load_gzip_json(p); rows.append(x['result'])
        except Exception: pass
    return rows


def write_csv(path, rows, gz=False):
    path=Path(path); path.parent.mkdir(parents=True,exist_ok=True)
    if not rows:
        if gz:
            with gzip.open(path,'wt') as f: f.write('')
        else: path.write_text('')
        return
    fields=[]
    for r in rows:
        for k in r:
            if k not in fields: fields.append(k)
    opener=(lambda p:gzip.open(p,'wt',newline='')) if gz else (lambda p:open(p,'w',newline=''))
    with opener(path) as f:
        w=csv.DictWriter(f,fieldnames=fields); w.writeheader();
        for r in rows: w.writerow({k:r.get(k) for k in fields})


def aggregate(out_dir:Path, science_seeds=SCIENCE_SEEDS):
    out_dir=Path(out_dir); results=collect_results(out_dir)
    terminal=[x for r in results for x in r['terminal']]
    checkpoints=[dict(x,seed=r['seed'],load=r['load']) for r in results for x in r['checkpoints']]
    revision=[dict(x,seed=r['seed'],load=r['load']) for r in results for x in r['revision']]
    geometry=[dict(x,seed=r['seed'],load=r['load']) for r in results for x in r['geometry']]
    costs=[x for r in results for x in r['state_costs']]
    ievents=[dict(x,seed=r['seed'],load=r['load']) for r in results for x in r['interference_events']]
    isum=[x for r in results for x in r['interference_summary']]
    sched=[]
    for r in results:
        s=r['schedule']; sched.append({'seed':r['seed'],'load':r['load'],'corr_count':s['corr_count'],'rand_count':s['rand_count'],'ordinary_count':s['ordinary_count'],'corr_hash':s['corr_hash'],'rand_hash':s['rand_hash'],'verifier_peak':s['verifier_peak']})
    budget=[dict(seed=r['seed'],load=r['load'],**r['sample_budget']) for r in results]
    devrows=[]
    for seed in science_seeds:
        p=out_dir/'development'/f'S{seed}.json'
        if p.exists():
            m=json.loads(p.read_text()); devrows.append({'seed':seed,'pair_updates':m['pair_updates'],'false_pair_rate':m['false_pair_rate'],'rank_pair':m['rank_pair'],'rank_shuffled':m['rank_shuffled'],'rank_random':m['rank_random'],'orth_pair_error':m['orth_pair_error'],'dev_records':m['dev_records'],'dev_raw_byte_budget':m['dev_raw_byte_budget']})
    # Per-arm descriptive summaries.
    summary=[]
    for load in sorted(set(x['load'] for x in terminal)):
        for arm in ALL_REPORT_ARMS:
            rs=[x for x in terminal if x['load']==load and x['arm']==arm]
            if not rs: continue
            row={'load':load,'arm':arm,'n':len(rs)}
            for k in ('whole_bpb','whole_accuracy','target_bpb','target_accuracy','nontarget_bpb','D_after_D_trained_accuracy','D_after_D_trained_bpb','heldout_after_D_accuracy','heldout_after_D_bpb'):
                row[k]=interval([x[k] for x in rs])
            summary.append(row)

    # Primary contrasts at load 256.
    contrast_specs=[
        ('G4_REPRESENTATION','PAIR-RAND','RAW-RAND'),
        ('G5_CORROBORATION','PAIR-CORR','PAIR-RAND'),
        ('G6_SHUFFLED','PAIR-CORR','SHUFFLED-PAIR-CORR'),
        ('G6_RANDOM_SUBSPACE','PAIR-CORR','RANDOM-SUBSPACE-CORR'),
        ('RAW_CORR_EFFECT','RAW-CORR','RAW-RAND'),
    ]
    contrasts=[]
    for name,left,right in contrast_specs:
        row={'contrast':name,'left':left,'right':right,'load':PRIMARY_LOAD}
        for key in ('heldout_after_D_bpb','D_after_D_trained_accuracy','whole_bpb','heldout_after_D_accuracy'):
            row[key]=paired(terminal,left,right,key,PRIMARY_LOAD)
        contrasts.append(row)
    # Factorial interaction: (PAIR-CORR - PAIR-RAND) - (RAW-CORR - RAW-RAND)
    by=collections.defaultdict(dict)
    for x in terminal:
        if x['load']==PRIMARY_LOAD: by[x['seed']][x['arm']]=x
    vals=[]
    for seed,a in by.items():
        need=('PAIR-CORR','PAIR-RAND','RAW-CORR','RAW-RAND')
        if all(n in a for n in need):
            vals.append((a['PAIR-CORR']['heldout_after_D_bpb']-a['PAIR-RAND']['heldout_after_D_bpb'])-(a['RAW-CORR']['heldout_after_D_bpb']-a['RAW-RAND']['heldout_after_D_bpb']))
    factorial=[{'endpoint':'heldout_after_D_bpb','interaction':interval(vals),'interpretation':'negative means corroboration is more beneficial under PAIR'}]

    # Gates.
    g0_file=out_dir/'FIREWALL_AUDIT.json'; r_file=out_dir/'RESUME_AUDIT.json'
    g0=bool(g0_file.exists() and r_file.exists() and json.loads(g0_file.read_text()).get('passed') and json.loads(r_file.read_text()).get('passed'))
    dev_complete=len(devrows)==len(science_seeds)
    g1_stats={'pair_updates':interval([x['pair_updates'] for x in devrows]),'false_pair_rate':interval([x['false_pair_rate'] for x in devrows])}
    g1=bool(dev_complete and g1_stats['pair_updates']['mean'] is not None and g1_stats['pair_updates']['mean']>=300 and g1_stats['false_pair_rate']['mean'] is not None and g1_stats['false_pair_rate']['mean']<=.05 and all(x['rank_pair']==20 for x in devrows))
    # G2 from load-256 geometry.
    gm=collections.defaultdict(dict)
    for x in geometry:
        if x['load']==PRIMARY_LOAD: gm[x['seed']][x['representation']]=x['margin']
    def gdiff(l,r): return interval([d[l]-d[r] for d in gm.values() if l in d and r in d and d[l] is not None and d[r] is not None])
    gp_raw,gp_shuf,gp_rand=gdiff('PAIR','RAW'),gdiff('PAIR','SHUFFLED'),gdiff('PAIR','RANDOM')
    g2=bool(gp_raw['mean'] is not None and gp_raw['mean']>=.05 and gp_raw['low']>0 and gp_shuf['mean']>=.02 and gp_shuf['low']>0 and gp_rand['mean']>=.05 and gp_rand['low']>0)
    # G3 acquisition.
    def levels(arm,key): return [x[key] for x in terminal if x['load']==PRIMARY_LOAD and x['arm']==arm]
    pr=levels('PAIR-RAND','D_after_D_trained_accuracy'); pc=levels('PAIR-CORR','D_after_D_trained_accuracy')
    g3=bool(len(pr)==16 and len(pc)==16 and sum(x>=.90 for x in pr)>=14 and sum(x>=.90 for x in pc)>=14 and np.mean(pr)>=.90 and np.mean(pc)>=.90)
    cdict={x['contrast']:x for x in contrasts}
    dR=cdict['G4_REPRESENTATION']; dC=cdict['G5_CORROBORATION']; dS=cdict['G6_SHUFFLED']; dN=cdict['G6_RANDOM_SUBSPACE']
    g4=bool(dR['heldout_after_D_bpb']['mean'] is not None and dR['heldout_after_D_bpb']['mean']<=-.10 and dR['heldout_after_D_bpb']['high']<0 and dR['D_after_D_trained_accuracy']['low']>=-.02 and dR['whole_bpb']['mean']<=.10)
    g5=bool(dC['heldout_after_D_bpb']['mean'] is not None and dC['heldout_after_D_bpb']['mean']<=-.10 and dC['heldout_after_D_bpb']['high']<0 and dC['D_after_D_trained_accuracy']['low']>=-.02 and dC['whole_bpb']['mean']<=.10)
    g6=bool(all(d['heldout_after_D_bpb']['mean'] is not None and d['heldout_after_D_bpb']['mean']<=-.05 and d['heldout_after_D_bpb']['high']<0 for d in (dS,dN)))
    # G7 interference pair-rand vs raw-rand, per seed all category.
    iby=collections.defaultdict(dict)
    for x in isum:
        if x['load']==PRIMARY_LOAD and x['category']=='all': iby[x['seed']][x['arm']]=x['mean_delta_bpb']
    rawvals=[d['RAW-RAND'] for d in iby.values() if 'RAW-RAND'in d and 'PAIR-RAND'in d]; diffs=[d['PAIR-RAND']-d['RAW-RAND'] for d in iby.values() if 'RAW-RAND'in d and 'PAIR-RAND'in d]
    g7diff=interval(diffs); rawmean=float(np.mean(rawvals)) if rawvals else None; pairmean=rawmean+(g7diff['mean'] or 0) if rawmean is not None else None
    reduction=None if rawmean is None or rawmean<=0 else (rawmean-pairmean)/rawmean
    g7=bool(g7diff['mean'] is not None and g7diff['high']<0 and reduction is not None and reduction>=.20)
    # G8 state.
    distributed_costs=[x for x in costs if x['arm'] in ARMS]
    g8=bool(distributed_costs and max(x['slow_semantic_bytes'] for x in distributed_costs)<=STATE_CAP_BYTES)
    # Ensure architecture allocations do not depend on load: the charged capacity is exact.
    for arm in ARMS:
        lv={x['load']:x['slow_semantic_bytes'] for x in distributed_costs if x['arm']==arm}
        if PRIMARY_LOAD in lv and SECONDARY_LOAD in lv and lv[PRIMARY_LOAD]!=lv[SECONDARY_LOAD]: g8=False
    if not g0: verdict='INVALID_IMPLEMENTATION'
    elif not g1: verdict='INVALID_DEVELOPMENT_SIGNAL'
    elif not g2: verdict='REPRESENTATION_EFFECT_NOT_REPLICATED'
    elif not g8: verdict='UNBOUNDED_OR_BUDGET_VIOLATION'
    elif not g3: verdict='ACQUISITION_TRADEOFF'
    elif g4 and g5 and g6: verdict='QUALIFIED_SLOT_FREE_CORE'
    elif g4 and g6 and not g5: verdict='REPRESENTATION_CORE_SUPPORTED'
    elif g5 and not g4: verdict='CORROBORATION_ONLY'
    elif (g4 or g5) and not g6: verdict='PAIR_SPECIFICITY_FAILED'
    else: verdict='NO_PERSISTENT_GAIN'
    gates={'G0_implementation':g0,'G1_development':g1,'G1_stats':g1_stats,
           'G2_representation':g2,'G2_pair_vs_raw':gp_raw,'G2_pair_vs_shuffled':gp_shuf,'G2_pair_vs_random':gp_rand,
           'G3_acquisition':g3,'G4_representation_persistence':g4,'G5_corroboration':g5,'G6_specificity':g6,
           'G7_interference_support':g7,'G7_pair_minus_raw':g7diff,'G7_relative_reduction':reduction,
           'G8_bounded_state':g8,'G9_slot_reference_nonqualifying':True,'verdict':verdict}

    # Persist outputs.
    write_csv(out_dir/'DEVELOPMENT_AUDIT.csv',devrows)
    write_csv(out_dir/'REPRESENTATION_GEOMETRY.csv',geometry)
    write_csv(out_dir/'TERMINAL.csv',terminal)
    write_csv(out_dir/'CHECKPOINT_METRICS.csv.gz',checkpoints,gz=True)
    # Flatten contrast stats for CSV readability.
    flat=[]
    for x in contrasts:
        r={'contrast':x['contrast'],'left':x['left'],'right':x['right'],'load':x['load']}
        for k,v in x.items():
            if isinstance(v,dict):
                for s,val in v.items(): r[f'{k}_{s}']=val
        flat.append(r)
    write_csv(out_dir/'PERSISTENCE_CONTRASTS.csv',flat)
    ff=[]
    for x in factorial:
        r={'endpoint':x['endpoint'],'interpretation':x['interpretation']}; r.update({f'interaction_{k}':v for k,v in x['interaction'].items()}); ff.append(r)
    write_csv(out_dir/'FACTORIAL_CONTRASTS.csv',ff)
    write_csv(out_dir/'STATE_COSTS.csv',costs)
    write_csv(out_dir/'SAMPLE_BUDGET.csv',budget)
    write_csv(out_dir/'WRITE_SCHEDULE_AUDIT.csv',sched)
    write_csv(out_dir/'INTERFERENCE_SUMMARY.csv',isum)
    write_csv(out_dir/'INTERFERENCE_EVENTS.csv.gz',ievents,gz=True)
    write_csv(out_dir/'REVISION.csv',revision)
    atomic_json(out_dir/'GATES.json',gates)
    atomic_json(out_dir/'REPORT.json',{'summary':summary,'contrasts':contrasts,'factorial':factorial,'gates':gates})
    manifest={'version':VERSION,'source_sha256':source_sha(),'design_sha256':DESIGN_SHA256,
              'candidate_A_sha256':CANDIDATE_A_SHA256,'candidate_C_sha256':CANDIDATE_C_SHA256,
              'science_seeds':list(science_seeds),'loads':[PRIMARY_LOAD,SECONDARY_LOAD],
              'numpy':np.__version__,'scipy':None if scipy is None else scipy.__version__,
              'platform':platform.platform(),'records':len(results),'verdict':verdict}
    atomic_json(out_dir/'MANIFEST.json',manifest)
    (out_dir/'PROTOCOL.md').write_text(DESIGN_TEXT)
    # Human-readable summary.
    lines=['# V45 results — Invariance-Guided Distributed Consolidation','',f'**Verdict:** `{verdict}`','',
           f'- G0 implementation: **{g0}**',f'- G1 development: **{g1}**',f'- G2 representation replication: **{g2}**',f'- G3 acquisition: **{g3}**',f'- G4 representation persistence: **{g4}**',f'- G5 corroboration: **{g5}**',f'- G6 specificity: **{g6}**',f'- G7 interference support: **{g7}**',f'- G8 bounded state: **{g8}**','',
           '## Primary load-256 contrasts','']
    for x in contrasts:
        s=x['heldout_after_D_bpb']; lines.append(f"- `{x['left']} - {x['right']}` heldout bpb: {s['mean'] if s['mean'] is not None else 'n/a'} [{s['low']}, {s['high']}]")
    lines += ['', 'Slot hybrid is an incumbent reference only and does not enter qualification gates.']
    (out_dir/'SUMMARY.md').write_text('\n'.join(lines)+'\n')
    return gates


def package_upload(out_dir:Path):
    out_dir=Path(out_dir); target=out_dir/'v45_results_upload.zip'
    include=['MANIFEST.json','PROTOCOL.md','GATES.json','SUMMARY.md','REPORT.json','DEVELOPMENT_AUDIT.csv','REPRESENTATION_GEOMETRY.csv','TERMINAL.csv','CHECKPOINT_METRICS.csv.gz','PERSISTENCE_CONTRASTS.csv','FACTORIAL_CONTRASTS.csv','STATE_COSTS.csv','SAMPLE_BUDGET.csv','WRITE_SCHEDULE_AUDIT.csv','INTERFERENCE_SUMMARY.csv','INTERFERENCE_EVENTS.csv.gz','REVISION.csv','RESUME_AUDIT.json','FIREWALL_AUDIT.json']
    with zipfile.ZipFile(target,'w',compression=zipfile.ZIP_DEFLATED) as z:
        for name in include:
            p=out_dir/name
            if p.exists(): z.write(p,arcname=name)
        z.write(SOURCE,arcname=SOURCE.name)
    return target


# -----------------------------------------------------------------------------
# Runner
# -----------------------------------------------------------------------------

def run_parallel(tasks, worker, workers):
    if not tasks: return []
    if int(workers)<=1: return [worker(t) for t in tasks]
    ctx=mp.get_context('spawn')
    out=[]
    with concurrent.futures.ProcessPoolExecutor(max_workers=int(workers),mp_context=ctx) as ex:
        futs={ex.submit(worker,t):t for t in tasks}
        for fut in concurrent.futures.as_completed(futs):
            out.append(fut.result())
    return out


def main(argv=None):
    ap=argparse.ArgumentParser(description=__doc__,formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('--self-test',action='store_true')
    ap.add_argument('--engineering-check',action='store_true')
    ap.add_argument('--stage',choices=('development','primary','scale','all','aggregate'),default='all')
    ap.add_argument('--out-dir',type=Path,default=Path('v45_results'))
    ap.add_argument('--workers',type=int,default=int(os.environ.get('V45_WORKERS','4')))
    ap.add_argument('--seeds',type=int,help='Non-scientific prefix of seed roster.')
    ap.add_argument('--smoke',action='store_true')
    ap.add_argument('--skip-engineering',action='store_true')
    args=ap.parse_args(argv)

    if args.self_test:
        print(json.dumps(static_self_test(),indent=2,sort_keys=True)); return 0
    out=args.out_dir; out.mkdir(parents=True,exist_ok=True)
    seeds=list(ENGINEERING_SEEDS if args.smoke else (SCIENCE_SEEDS[:args.seeds] if args.seeds else SCIENCE_SEEDS))
    scientific=not args.smoke and args.seeds is None
    if args.engineering_check:
        print(json.dumps(engineering_check(out,args.workers),indent=2,sort_keys=True)); return 0
    if args.stage=='all' and not args.skip_engineering and scientific:
        if not (out/'RESUME_AUDIT.json').exists():
            print('Running required engineering/resume audit...',flush=True); engineering_check(out,args.workers)
    if args.stage in ('development','all','primary','scale'):
        tasks=[(s,str(out),args.smoke) for s in seeds]
        print(f'Development: {len(tasks)} seeds, workers={args.workers}',flush=True)
        for r in run_parallel(tasks,run_development_worker,args.workers): print('  dev',r,flush=True)
    if args.stage in ('primary','all'):
        load=64 if args.smoke else PRIMARY_LOAD; tasks=[(s,load,str(out),args.smoke) for s in seeds]
        print(f'Primary persistent: load={load}, {len(tasks)} seed jobs',flush=True)
        for r in run_parallel(tasks,run_persistent_worker,args.workers):
            rr=r.get('result'); print('  primary',rr and {'seed':rr['seed'],'load':rr['load'],'seconds':round(rr['elapsed_seconds'],1)},flush=True)
    if args.stage in ('scale','all') and not args.smoke:
        tasks=[(s,SECONDARY_LOAD,str(out),False) for s in seeds]
        print(f'Scale persistent: load={SECONDARY_LOAD}, {len(tasks)} seed jobs',flush=True)
        for r in run_parallel(tasks,run_persistent_worker,args.workers):
            rr=r.get('result'); print('  scale',rr and {'seed':rr['seed'],'load':rr['load'],'seconds':round(rr['elapsed_seconds'],1)},flush=True)
    if args.stage in ('aggregate','all','primary','scale'):
        gates=aggregate(out,seeds if scientific else seeds)
        print('Verdict:',gates['verdict'],flush=True)
        if args.stage=='all' and scientific:
            z=package_upload(out); print('Upload bundle:',z,flush=True)
    return 0


if __name__=='__main__':
    raise SystemExit(main())
